alter table public.websites add column if not exists traffic_trend_month date;
comment on column public.websites.traffic_trend_month is 'The calendar month (first of the month) that the last element of traffic_trend was measured in. Null until the refresh has recorded a reading. The refresh replaces the last element when a new reading falls in this same month, and appends otherwise, so the series is one point per month however often the listing is refreshed. Consecutive months are not guaranteed: a listing nobody refreshed in a given month simply has no reading for it, and nothing should label the array as a continuous run of months.';
